'use strict';
globalThis.LoopCartridge=(()=>{
// Both the blueprint builder and the live worker use this exact seed stream.
function rng(seed) {
  let state = seed >>> 0;
  return () => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return state / 4294967296;
  };
}
function neighbors(i, size) {
  const x = i % size,
    y = Math.floor(i / size);
  return [
    [x - 1, y],
    [x + 1, y],
    [x, y - 1],
    [x, y + 1],
  ]
    .filter(([a, b]) => a >= 0 && b >= 0 && a < size && b < size)
    .map(([a, b]) => b * size + a);
}
function route(grid, size, from, to) {
  const queue = [from],
    previous = new Map([[from, -1]]);
  for (let head = 0; head < queue.length; head++) {
    const current = queue[head];
    if (current === to) {
      const path = [];
      for (let i = to; i !== from; i = previous.get(i)) path.push(i);
      return path.reverse();
    }
    for (const next of neighbors(current, size)) {
      if (grid[next] && !previous.has(next)) {
        previous.set(next, current);
        queue.push(next);
      }
    }
  }
  return [];
}

// Cartridge ABI. Coordinates are normalized. State and drawing commands are JSON.
function baseStart(L) {
  return {
    score: 0,
    hits: 0,
    elapsed: 0,
    done: false,
    won: false,
    cell: L.from || 0,
    lane: 1,
    mistakes: 0,
  };
}
function inCell(index, L) {
  return { x: ((index % L.size) + 0.5) / L.size, y: (Math.floor(index / L.size) + 0.5) / L.size };
}
function baseStep(s, e, L) {
  if (s.done) return s;
  if (e.type === 'tick') {
    s.elapsed += e.dt;
    if (s.elapsed >= L.seconds) {
      s.done = true;
      return s;
    }
  }
  const point = L.points[s.hits % L.points.length];
  if (L.family === 'trail' && (e.type === 'tap' || e.type === 'key')) {
    let next = s.cell;
    if (e.type === 'tap') next = Math.floor(e.y * L.size) * L.size + Math.floor(e.x * L.size);
    else next += { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -L.size, ArrowDown: L.size }[e.key] || 0;
    if (neighbors(s.cell, L.size).includes(next) && L.grid[next]) {
      s.cell = next;
      s.score++;
      s.hits++;
      if (next === L.to) s.won = s.done = true;
    }
  } else if (L.family === 'drift') {
    if (e.type === 'tap') s.lane = Math.min(2, Math.floor(e.x * 3));
    if (e.type === 'key')
      s.lane = Math.max(0, Math.min(2, s.lane + ({ ArrowLeft: -1, ArrowRight: 1 }[e.key] || 0)));
    if (e.type === 'tick' && Math.floor(s.elapsed / L.pace) > s.hits + s.mistakes) {
      if (s.lane === point.lane) {
        s.score += 10;
        s.hits++;
      } else s.mistakes++;
    }
    if (s.hits >= L.quota) s.won = s.done = true;
  } else if (L.family !== 'trail' && e.type === 'tap') {
    if (Math.hypot(e.x - point.x, e.y - point.y) <= L.radius) {
      s.hits++;
      s.score += 10;
    } else s.mistakes++;
    if (s.hits >= L.quota) s.won = s.done = true;
  }
  return s;
}
function baseDraw(s, L) {
  const commands = [],
    point = L.points[s.hits % L.points.length];
  if (L.family === 'trail') {
    const w = 1 / L.size;
    for (let i = 0; i < L.grid.length; i++)
      if (!L.grid[i]) {
        const p = inCell(i, L);
        commands.push({
          kind: 'rect',
          x: p.x - w * 0.46,
          y: p.y - w * 0.46,
          w: w * 0.92,
          h: w * 0.92,
          color: 'ink',
        });
      }
    commands.push({ kind: 'circle', ...inCell(L.to, L), r: w * 0.36, color: 'accent' });
    commands.push({ kind: 'sprite', ...inCell(s.cell, L), r: w * 0.46 });
  } else if (L.family === 'drift') {
    for (let i = 1; i < 3; i++)
      commands.push({ kind: 'line', x: i / 3, y: 0.02, x2: i / 3, y2: 0.98, color: 'soft' });
    const phase = (s.elapsed % L.pace) / L.pace;
    commands.push({
      kind: 'circle',
      x: (point.lane + 0.5) / 3,
      y: 0.09 + phase * 0.74,
      r: 0.045,
      color: 'accent',
    });
    commands.push({ kind: 'sprite', x: (s.lane + 0.5) / 3, y: 0.88, r: 0.07 });
  } else {
    for (let i = 1; i < 4; i++) {
      const upcoming = L.points[(s.hits + i) % L.points.length];
      commands.push({ kind: 'ring', x: upcoming.x, y: upcoming.y, r: 0.014, color: 'soft' });
    }
    commands.push({
      kind: 'ring',
      x: point.x,
      y: point.y,
      r: L.radius * (1.1 + 0.1 * Math.sin(s.elapsed * 4)),
      color: 'accent',
    });
    commands.push({ kind: 'sprite', x: point.x, y: point.y, r: L.radius * 0.8 });
  }
  return commands;
}
function baseWitness(s, L) {
  if (L.family === 'trail') {
    const next = route(L.grid, L.size, s.cell, L.to)[0];
    return { type: 'tap', ...inCell(next, L) };
  }
  const point = L.points[s.hits % L.points.length];
  if (L.family === 'drift') {
    if (s.lane !== point.lane) return { type: 'tap', x: (point.lane + 0.5) / 3, y: 0.8 };
    return { type: 'tick', dt: 0.1 };
  }
  return { type: 'tap', x: point.x, y: point.y };
}

function qOf(L) {
  const want = [1, 3, 5][(L.index || 1) - 1] || 3;
  return Math.max(1, Math.min(want, (L.points || []).length));
}
function graceOf(L) {
  return [5, 3.5, 2.5][(L.index || 1) - 1] || 4;
}
function start(L) {
  return { score: 0, hits: 0, elapsed: 0, done: false, won: false, u: 0, tilt: 0, vignette: 0, dockT: 0, mistakes: 0, over: false, driftT: 0, driftX: 0 };
}
function pathOf(L) {
  const n = qOf(L), p = [{ x: 0.5, y: 0.92 }];
  for (let i = 0; i < n; i++) p.push({ x: L.points[i].x, y: L.points[i].y });
  p.push({ x: 0.5, y: 0.12 });
  const cum = [0];
  for (let i = 1; i < p.length; i++) cum.push(cum[i - 1] + Math.hypot(p[i].x - p[i - 1].x, p[i].y - p[i - 1].y));
  return { p: p, cum: cum, total: cum[cum.length - 1] };
}
function posAt(P, u) {
  for (let i = 1; i < P.p.length; i++) if (u <= P.cum[i]) {
    const f = (u - P.cum[i - 1]) / (P.cum[i] - P.cum[i - 1] || 1);
    return { x: P.p[i - 1].x + (P.p[i].x - P.p[i - 1].x) * f, y: P.p[i - 1].y + (P.p[i].y - P.p[i - 1].y) * f };
  }
  return P.p[P.p.length - 1];
}
function reefOf(L, i) {
  const b = L.points[Math.min(i, L.points.length - 1)];
  return { x: b.x < 0.5 ? b.x - 0.16 : b.x + 0.16, y: b.y, r: 0.06 };
}
function step(s, e, L) {
  if (s.done) return s;
  const n = qOf(L), P = pathOf(L), g = graceOf(L);
  const speed = (P.total / (n + 1)) / (g * 0.8) * (1 + 0.2 * s.hits) * (s.over ? 0.4 : 1);
  if (e.type === 'tap') {
    if (s.hits < n) {
      const b = L.points[s.hits];
      if (Math.hypot(e.x - b.x, e.y - b.y) <= L.radius) {
        s.hits++; s.score += 10;
        if (s.over) { s.over = false; s.driftT = 0; s.driftX = 0; }
      } else s.mistakes++;
    }
  } else if (e.type === 'tick') {
    s.elapsed += e.dt;
    if (s.vignette > 0) s.vignette = Math.max(0, s.vignette - e.dt / 0.8);
    if (s.won && s.dockT > 0) s.dockT = Math.max(0, s.dockT - e.dt);
    s.u = Math.min(s.u + speed * e.dt, P.total);
    if (s.hits < n && s.u >= P.cum[s.hits + 1]) s.over = true;
    if (s.over) {
      s.driftT += e.dt;
      s.driftX += (L.points[s.hits].x < 0.5 ? -1 : 1) * 0.05 * e.dt;
      if (s.driftT >= g) { s.done = true; s.tilt = 1; s.vignette = 1; return s; }
    }
    if (s.hits >= n && s.u >= P.total) { s.done = true; s.won = true; s.dockT = 1.5; s.score += 20; }
    else if (s.elapsed >= L.seconds) { s.done = true; s.vignette = 1; }
  }
  return s;
}
function draw(s, L) {
  const c = [], n = qOf(L), P = pathOf(L), ship = posAt(P, s.u);
  c.push({ kind: 'rect', x: 0, y: 0, w: 1, h: 1, color: 'background' });
  for (let i = 0.1; i < 1; i += 0.2) for (let j = 0.1; j < 1; j += 0.2) c.push({ kind: 'circle', x: i, y: j, r: 0.004, color: 'soft' });
  for (let i = 1; i < P.p.length; i++) c.push({ kind: 'line', x: P.p[i - 1].x, y: P.p[i - 1].y, x2: P.p[i].x, y2: P.p[i].y, color: i <= s.hits ? 'accent' : 'soft' });
  if (s.over || s.hits < n) { const r = reefOf(L, s.hits); c.push({ kind: 'sprite', asset: 'reef', x: r.x, y: r.y, r: r.r }); }
  if (s.hits > 0) { const a = P.p[s.hits], b = posAt(P, s.u); c.push({ kind: 'line', x: a.x, y: a.y, x2: b.x, y2: b.y, color: 'accent' }); }
  for (let i = 0; i < n; i++) {
    const b = L.points[i];
    if (i < s.hits) {
      const ph = (s.elapsed * 0.8 + i * 0.3) % 1;
      c.push({ kind: 'circle', x: b.x, y: b.y, r: L.radius * 0.4, color: 'accent' });
      c.push({ kind: 'ring', x: b.x, y: b.y, r: L.radius * (0.5 + ph * 0.6), color: 'accent' });
      c.push({ kind: 'ring', x: b.x, y: b.y, r: L.radius * (0.3 + ph * 0.4), color: 'accent' });
    } else {
      const on = i === s.hits && !s.done;
      c.push({ kind: 'circle', x: b.x, y: b.y, r: on ? 0.02 + 0.008 * Math.sin(s.elapsed * 6) : 0.015, color: on ? 'accent' : 'ink' });
      if (on) c.push({ kind: 'ring', x: b.x, y: b.y, r: L.radius, color: 'accent' });
    }
  }
  c.push({ kind: 'sprite', asset: 'mailship', x: ship.x + s.driftX, y: ship.y, r: 0.05 });
  c.push({ kind: 'sprite', asset: 'lighthouse', x: 0.5, y: 0.1, r: 0.07 });
  if (s.won) {
    const ph = (s.elapsed * 0.6) % 1;
    c.push({ kind: 'ring', x: 0.5, y: 0.07, r: 0.05 + ph * 0.2, color: 'accent' });
    c.push({ kind: 'text', x: 0.5, y: 0.3, text: '入港', size: 0.06, color: 'ink' });
  }
  if (s.done && !s.won) {
    c.push({ kind: 'rect', x: 0, y: 0, w: 1, h: 0.06, color: 'ink' });
    c.push({ kind: 'rect', x: 0, y: 0.94, w: 1, h: 0.06, color: 'ink' });
    c.push({ kind: 'text', x: 0.5, y: 0.3, text: '触礁，重来', size: 0.05, color: '#E63946' });
  }
  if (!s.done) c.push({ kind: 'text', x: 0.5, y: 0.045, text: '信标 ' + s.hits + '/' + n, size: 0.035, color: 'ink' });
  return c;
}
function witness(s, L) {
  if (s.done) return { type: 'tick', dt: 0.1 };
  if (s.hits < qOf(L)) { const b = L.points[s.hits]; return { type: 'tap', x: b.x, y: b.y }; }
  return { type: 'tick', dt: 0.1 };
}

